  function openObjectLibraryDb() {
    if (objectLibraryDbPromise) return objectLibraryDbPromise;
    objectLibraryDbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(OBJECT_LIBRARY_DB, 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(OBJECT_LIBRARY_STORE)) {
          const store = db.createObjectStore(OBJECT_LIBRARY_STORE, { keyPath: "id" });
          store.createIndex("objectType", "objectType", { unique: false });
          store.createIndex("updatedAt", "updatedAt", { unique: false });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error("No se pudo abrir la biblioteca local."));
    });
    return objectLibraryDbPromise;
  }

  function hashAssetSource(value) {
    let hash = 2166136261;
    const input = String(value || "");
    for (let index = 0; index < input.length; index += Math.max(1, Math.floor(input.length / 10000))) {
      hash ^= input.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(36);
  }

  async function getAllObjectAssetsForType(objectType) {
    if (!objectType) return [];
    const db = await openObjectLibraryDb();
    const records = await new Promise((resolve, reject) => {
      const transaction = db.transaction(OBJECT_LIBRARY_STORE, "readonly");
      const store = transaction.objectStore(OBJECT_LIBRARY_STORE);
      const index = store.index("objectType");
      const request = index.getAll(IDBKeyRange.only(objectType));
      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error || transaction.error);
    });
    return records.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0));
  }

  async function getRecentObjectAssets(objectType, { fresh = false } = {}) {
    if (!objectType) return [];
    if (!fresh && recentObjectAssetsCache.has(objectType)) return recentObjectAssetsCache.get(objectType);
    const ordered = (await getAllObjectAssetsForType(objectType)).slice(0, OBJECT_LIBRARY_LIMIT);
    recentObjectAssetsCache.set(objectType, ordered);
    return ordered;
  }

  async function saveRecentObjectAsset(objectType, rasterized, name) {
    if (!objectType || !rasterized?.dataUrl) return;
    const now = Date.now();
    const record = {
      id: `${objectType}:${hashAssetSource(rasterized.dataUrl)}`,
      objectType,
      name: String(name || "Imagen importada").slice(0, 180),
      mime: "image/png",
      dataUrl: rasterized.dataUrl,
      width: Math.max(1, Number(rasterized.width) || 1),
      height: Math.max(1, Number(rasterized.height) || 1),
      aspect: Math.max(.05, Number(rasterized.width) / Math.max(1, Number(rasterized.height))),
      createdAt: now,
      updatedAt: now
    };
    const db = await openObjectLibraryDb();
    await new Promise((resolve, reject) => {
      const transaction = db.transaction(OBJECT_LIBRARY_STORE, "readwrite");
      transaction.objectStore(OBJECT_LIBRARY_STORE).put(record);
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
    });
    recentObjectAssetsCache.delete(objectType);
    const all = await getAllObjectAssetsForType(objectType);
    if (all.length > OBJECT_LIBRARY_LIMIT) {
      await Promise.all(all.slice(OBJECT_LIBRARY_LIMIT).map(asset => deleteRecentObjectAsset(asset.id, objectType, { refresh: false })));
    }
    recentObjectAssetsCache.set(objectType, all.slice(0, OBJECT_LIBRARY_LIMIT));
  }

  async function migrateProjectObjectImagesToLibrary(data) {
    if (!data?.elements?.length) return;
    const seen = new Set();
    for (const element of data.elements) {
      if (!isImageEligible(element) || !element.customImageData) continue;
      const key = `${element.type}:${hashAssetSource(element.customImageData)}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const aspect = Math.max(.05, Number(element.customImageAspect) || 1);
      await saveRecentObjectAsset(element.type, {
        dataUrl: element.customImageData,
        width: Math.max(1, Math.round(1000 * aspect)),
        height: 1000
      }, element.customImageName || "Imagen importada");
    }
  }

  async function touchRecentObjectAsset(record) {
    if (!record?.id) return;
    const db = await openObjectLibraryDb();
    await new Promise((resolve, reject) => {
      const transaction = db.transaction(OBJECT_LIBRARY_STORE, "readwrite");
      transaction.objectStore(OBJECT_LIBRARY_STORE).put({ ...record, updatedAt: Date.now() });
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
    });
    recentObjectAssetsCache.delete(record.objectType);
  }

  async function deleteRecentObjectAsset(id, objectType, { refresh = true } = {}) {
    if (!id) return;
    const db = await openObjectLibraryDb();
    await new Promise((resolve, reject) => {
      const transaction = db.transaction(OBJECT_LIBRARY_STORE, "readwrite");
      transaction.objectStore(OBJECT_LIBRARY_STORE).delete(id);
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
    });
    recentObjectAssetsCache.delete(objectType);
    if (refresh) renderRecentObjectAssets(selected());
  }

  async function renderRecentObjectAssets(element) {
    if (!els.recentObjectImagesWrap || !els.recentObjectImages || !els.recentObjectImagesEmpty) return;
    const eligible = isImageEligible(element);
    els.recentObjectImagesWrap.hidden = !eligible;
    if (!eligible) return;
    const token = ++recentLibraryRenderToken;
    const elementId = element.id;
    const objectType = element.type;
    els.recentObjectImagesType.textContent = TYPE_LABELS[objectType] || objectType;
    els.recentObjectImages.replaceChildren();
    els.recentObjectImagesEmpty.hidden = false;
    els.recentObjectImagesEmpty.textContent = "Cargando archivos locales…";
    try {
      const records = await getRecentObjectAssets(objectType);
      const current = selected();
      if (token !== recentLibraryRenderToken || !current || current.id !== elementId || current.type !== objectType) return;
      els.recentObjectImages.replaceChildren();
      els.recentObjectImagesEmpty.hidden = Boolean(records.length);
      els.recentObjectImagesEmpty.textContent = "Todavía no has importado imágenes para este tipo de objeto.";
      records.forEach(record => {
        const card = document.createElement("article");
        card.className = "dungeon-recent-asset";
        const applyButton = document.createElement("button");
        applyButton.type = "button";
        applyButton.className = "dungeon-recent-asset__apply";
        applyButton.title = `Usar ${record.name}`;
        const image = document.createElement("img");
        image.src = record.dataUrl;
        image.alt = "";
        const label = document.createElement("strong");
        label.textContent = record.name || "Imagen importada";
        applyButton.append(image, label);
        applyButton.addEventListener("click", async () => {
          const target = selected();
          if (!target || target.type !== objectType) return;
          target.customImageData = record.dataUrl;
          target.customImageName = record.name || "Imagen importada";
          target.customImageType = record.mime || "image/png";
          target.customImageAspect = Math.max(.05, Number(record.aspect) || 1);
          commit(`Imagen local aplicada a ${TYPE_LABELS[objectType] || "objeto"}`);
          try { await touchRecentObjectAsset(record); } catch (error) { console.warn("No se pudo actualizar el orden de recientes", error); }
        });
        const deleteButton = document.createElement("button");
        deleteButton.type = "button";
        deleteButton.className = "dungeon-recent-asset__delete";
        deleteButton.textContent = "×";
        deleteButton.title = "Eliminar de archivos recientes";
        deleteButton.setAttribute("aria-label", `Eliminar ${record.name || "imagen"} de archivos recientes`);
        deleteButton.addEventListener("click", async () => {
          if (!confirm(`¿Eliminar «${record.name || "Imagen importada"}» de los archivos recientes de ${TYPE_LABELS[objectType] || objectType}?`)) return;
          try { await deleteRecentObjectAsset(record.id, objectType); }
          catch (error) { console.error(error); alert("No se pudo eliminar la imagen de la biblioteca local."); }
        });
        card.append(applyButton, deleteButton);
        els.recentObjectImages.append(card);
      });
    } catch (error) {
      console.error(error);
      if (token !== recentLibraryRenderToken) return;
      els.recentObjectImages.replaceChildren();
      els.recentObjectImagesEmpty.hidden = false;
      els.recentObjectImagesEmpty.textContent = "No se pudo abrir la biblioteca local de imágenes.";
    }
  }

  function normaliseFloorMaterial(raw = {}) {
    return {
      texture: String(raw.texture || ""), color: String(raw.color || ""),
      scale: clamp(raw.scale || 4, .1, 12), rotation: clamp(raw.rotation || 0, 0, 360), intensity: clamp(raw.intensity || 1, .2, 1.4),
      mode: ["continuous", "cover", "repeat"].includes(raw.mode) ? raw.mode : "continuous",
      customData: String(raw.customData || ""), customName: String(raw.customName || "")
    };
  }

  function defaultProject() {
    return {
      version: 1, widthCells: 40, heightCells: 30, gridVisible: true, snap: true, preset: "stone",
      style: { ...clone(PRESETS.stone), ...clone(MATERIAL_DEFAULTS) }, elements: [], createdAt: app.now(), updatedAt: app.now()
    };
  }

  function normaliseProject(raw) {
    const base = defaultProject();
    if (!raw || typeof raw !== "object") return base;
    base.widthCells = Math.round(clamp(raw.widthCells || 40, 10, 120));
    base.heightCells = Math.round(clamp(raw.heightCells || 30, 10, 120));
    base.gridVisible = raw.gridVisible !== false;
    base.snap = raw.snap !== false;
    base.preset = PRESETS[raw.preset] ? raw.preset : "stone";
    base.style = { ...base.style, ...(raw.style || {}) };
    base.elements = Array.isArray(raw.elements) ? raw.elements.map(element => ({
      id: String(element.id || app.uid()), type: TYPE_LABELS[element.type] ? element.type : "room",
      x: Number(element.x) || 0, y: Number(element.y) || 0, w: Math.max(.25, Number(element.w) || 1), h: Math.max(.25, Number(element.h) || 1),
      x2: Number.isFinite(Number(element.x2)) ? Number(element.x2) : (Number(element.x) || 0) + 1,
      y2: Number.isFinite(Number(element.y2)) ? Number(element.y2) : (Number(element.y) || 0) + 1,
      rotation: Number(element.rotation) || 0, label: String(element.label || "").slice(0, 100), hidden: Boolean(element.hidden),
      floorTexture: String(element.floorTexture || ""),
      variant: element.type === "statue" ? normaliseStatueVariant(element.variant) : String(element.variant || ""),
      customImageData: String(element.customImageData || ""), customImageName: String(element.customImageName || ""), customImageType: String(element.customImageType || ""), customImageAspect: Math.max(.05, Number(element.customImageAspect) || 1),
      floorMaterial: normaliseFloorMaterial(element.floorMaterial || {})
    })) : [];
    base.createdAt = raw.createdAt || app.now();
    base.updatedAt = raw.updatedAt || app.now();
    return base;
  }

  function open(id) {
    const target = state().atlas?.scenes?.find(item => item.id === id);
    if (!target) return;
    sceneId = id;
    project = normaliseProject(target.mapProject);
    migrateProjectObjectImagesToLibrary(project).catch(error => console.warn("No se pudieron migrar todas las imágenes a la biblioteca local.", error));
    target.sourceType = "dungeon";
    target.mapProject = clone(project);
    selectedId = "";
    tool = "select";
    propTool = "";
    dirty = false;
    history = [JSON.stringify(project)];
    historyIndex = 0;
    app.setView("dungeon");
    syncForm();
    setTool("select");
    resizeCanvases();
    requestAnimationFrame(() => fitMap());
    renderAll();
  }

  function render() {
    if (state().view !== "dungeon" || !project) return;
    syncForm();
    resizeCanvases();
    renderAll();
  }

  function closeEditor() {
    persistProject();
    if (dirty && !confirm("Hay cambios que todavía no se han convertido en la imagen del Atlas. ¿Volver igualmente? El proyecto editable sí quedará guardado.")) return;
    app.setView("atlas");
    window.ForjaAtlas?.render?.();
  }

  function syncForm() {
    if (!project) return;
    const target = scene();
    els.title.textContent = target ? `Editor · ${target.name}` : "Editor de mazmorras";
    els.subtitle.textContent = `${project.widthCells} × ${project.heightCells} m · cada casilla representa 1 m²`;
    els.mapWidth.value = project.widthCells;
    els.mapHeight.value = project.heightCells;
    els.preset.value = project.preset;
    els.gridVisible.checked = project.gridVisible;
    els.snap.checked = project.snap;
    Object.entries({
      lineColor: "lineColor", doorColor: "doorColor", objectColor: "objectColor", textColor: "textColor", gridColor: "gridColor",
      lineWidth: "lineWidth", shadowOpacity: "shadowOpacity", relief: "relief"
    }).forEach(([elementKey, styleKey]) => { if (els[elementKey]) els[elementKey].value = project.style[styleKey]; });
    syncMaterialControls();
    updateHistoryButtons();
    renderSelectionPanel();
  }

