  function globalFloorMaterial() {
    return {
      texture: project.style.floorTexture, color: project.style.floorColor,
      scale: project.style.floorTextureScale, rotation: project.style.floorTextureRotation,
      intensity: project.style.floorTextureIntensity, mode: project.style.floorTextureMode,
      customData: project.style.floorCustomTextureData, customName: project.style.floorCustomTextureName
    };
  }

  function effectiveFloorMaterial(element = null) {
    const global = globalFloorMaterial();
    if (!element?.floorMaterial?.texture && !element?.floorMaterial?.customData && !element?.floorMaterial?.color) return global;
    return { ...global, ...element.floorMaterial };
  }

  function wallMaterial() {
    return {
      texture: project.style.wallTexture, color: project.style.wallColor,
      scale: project.style.wallTextureScale, rotation: project.style.wallTextureRotation,
      intensity: project.style.wallTextureIntensity, mode: project.style.wallTextureMode,
      customData: project.style.wallCustomTextureData, customName: project.style.wallCustomTextureName
    };
  }

  function currentFloorMaterial() {
    const targetSelection = els.floorMaterialTarget?.value === "selection";
    const element = selectedFloorElement();
    return targetSelection && element ? effectiveFloorMaterial(element) : globalFloorMaterial();
  }

  function syncMaterialControls() {
    if (!project) return;
    const selectedFloor = selectedFloorElement();
    if (els.floorMaterialTarget) {
      els.floorMaterialTarget.querySelector('option[value="selection"]').disabled = !selectedFloor;
      if (!selectedFloor && els.floorMaterialTarget.value === "selection") els.floorMaterialTarget.value = "global";
    }
    const floor = currentFloorMaterial();
    const wall = wallMaterial();
    els.floorTexture.value = floor.customData ? "custom" : (floor.texture || "stone-light");
    els.floorColor.value = floor.color || project.style.floorColor;
    els.floorTextureScale.value = floor.scale || 4;
    els.floorTextureRotation.value = floor.rotation || 0;
    els.floorTextureIntensity.value = floor.intensity || 1;
    els.floorTextureMode.value = floor.mode || "continuous";
    els.wallTexture.value = wall.customData ? "custom" : (wall.texture || "stone");
    els.wallColor.value = wall.color || project.style.wallColor;
    els.wallTextureScale.value = wall.scale || 2;
    els.wallTextureRotation.value = wall.rotation || 0;
    els.wallTextureIntensity.value = wall.intensity || 1;
    els.wallTextureMode.value = wall.mode || "continuous";
    updateMaterialOutputs();
    els.floorTextureName.textContent = floor.customName || "";
    els.wallTextureName.textContent = wall.customName || "";
    els.removeFloorTexture.hidden = !floor.customData;
    els.removeWallTexture.hidden = !wall.customData;
    renderMaterialPreviews();
  }

  function updateMaterialOutputs() {
    if (els.floorScaleValue) els.floorScaleValue.textContent = `${Number(els.floorTextureScale.value || 4).toFixed(1).replace('.0','')} m`;
    if (els.floorRotationValue) els.floorRotationValue.textContent = `${Math.round(Number(els.floorTextureRotation.value || 0))}°`;
    if (els.floorIntensityValue) els.floorIntensityValue.textContent = `${Math.round(Number(els.floorTextureIntensity.value || 1) * 100)}%`;
    if (els.wallScaleValue) els.wallScaleValue.textContent = `${Number(els.wallTextureScale.value || 2).toFixed(2).replace(/\.00$/,'').replace(/0$/,'')} m`;
    if (els.wallRotationValue) els.wallRotationValue.textContent = `${Math.round(Number(els.wallTextureRotation.value || 0))}°`;
    if (els.wallIntensityValue) els.wallIntensityValue.textContent = `${Math.round(Number(els.wallTextureIntensity.value || 1) * 100)}%`;
  }

  function setStatus(message) {
    els.status.textContent = message;
  }

  function resizeCanvases() {
    if (!project) return;
    const width = Math.round(project.widthCells * EDIT_CELL);
    const height = Math.round(project.heightCells * EDIT_CELL);
    [els.canvas, els.overlay].forEach(canvas => {
      if (canvas.width !== width) canvas.width = width;
      if (canvas.height !== height) canvas.height = height;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
    });
    els.stage.style.width = `${width}px`;
    els.stage.style.height = `${height}px`;
    applyTransform();
  }

  function applyTransform() {
    els.stage.style.transform = `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`;
  }

  function fitMap() {
    if (!project || !els.viewport.clientWidth || !els.viewport.clientHeight) return;
    const mapWidth = project.widthCells * EDIT_CELL;
    const mapHeight = project.heightCells * EDIT_CELL;
    const padding = 42;
    const scale = clamp(Math.min((els.viewport.clientWidth - padding * 2) / mapWidth, (els.viewport.clientHeight - padding * 2) / mapHeight), MIN_ZOOM, 1.5);
    transform.scale = scale;
    transform.x = (els.viewport.clientWidth - mapWidth * scale) / 2;
    transform.y = (els.viewport.clientHeight - mapHeight * scale) / 2;
    applyTransform();
  }

  function zoomBy(factor, anchor = null) {
    const rect = els.viewport.getBoundingClientRect();
    const point = anchor || { x: rect.width / 2, y: rect.height / 2 };
    const oldScale = transform.scale;
    const next = clamp(oldScale * factor, MIN_ZOOM, MAX_ZOOM);
    const mapX = (point.x - transform.x) / oldScale;
    const mapY = (point.y - transform.y) / oldScale;
    transform.scale = next;
    transform.x = point.x - mapX * next;
    transform.y = point.y - mapY * next;
    applyTransform();
  }

  function pointFromEvent(event) {
    const rect = els.overlay.getBoundingClientRect();
    const x = ((event.clientX - rect.left) / rect.width) * project.widthCells;
    const y = ((event.clientY - rect.top) / rect.height) * project.heightCells;
    return { x: clamp(x, 0, project.widthCells), y: clamp(y, 0, project.heightCells) };
  }

  function setTool(next, prop = "") {
    tool = next;
    propTool = prop;
    $$('[data-dungeon-tool]', els.tools).forEach(button => button.classList.toggle("is-active", button.dataset.dungeonTool === tool && !propTool));
    $$('[data-dungeon-prop]').forEach(button => button.classList.toggle("is-active", button.dataset.dungeonProp === propTool));
    els.viewport.dataset.tool = propTool || tool;
    setStatus(propTool ? `Coloca: ${TYPE_LABELS[propTool]}` : `Herramienta: ${toolLabel(tool)}`);
  }

  function toolLabel(value) {
    return ({ select: "Seleccionar", pan: "Mover vista", room: "Habitación", corridor: "Pasillo", wall: "Pared", text: "Texto", eraser: "Borrar" })[value] || value;
  }

  function persistProject() {
    clearTimeout(persistTimer);
    const target = scene();
    if (!target || !project) return;
    project.updatedAt = app.now();
    target.mapProject = clone(project);
    target.sourceType = "dungeon";
    target.updatedAt = app.now();
    app.saveState(true);
  }

  function schedulePersist() {
    clearTimeout(persistTimer);
    persistTimer = setTimeout(persistProject, 250);
  }

  function pushHistory() {
    const snapshot = JSON.stringify(project);
    if (history[historyIndex] === snapshot) return;
    history = history.slice(0, historyIndex + 1);
    history.push(snapshot);
    if (history.length > 80) history.shift();
    historyIndex = history.length - 1;
    dirty = true;
    schedulePersist();
    updateHistoryButtons();
  }

  function updateHistoryButtons() {
    els.undo.disabled = historyIndex <= 0;
    els.redo.disabled = historyIndex >= history.length - 1;
  }

  function restoreHistory(index) {
    if (index < 0 || index >= history.length) return;
    historyIndex = index;
    project = normaliseProject(JSON.parse(history[index]));
    if (!selected()) selectedId = "";
    dirty = true;
    persistProject();
    syncForm();
    resizeCanvases();
    renderAll();
  }

  function undo() { restoreHistory(historyIndex - 1); }
  function redo() { restoreHistory(historyIndex + 1); }

  function commit(message = "Cambios guardados en el proyecto") {
    project.updatedAt = app.now();
    pushHistory();
    persistProject();
    syncForm();
    renderAll();
    setStatus(message);
  }

  function elementBounds(element) {
    if (element.type === "wall") {
      return { x: Math.min(element.x, element.x2), y: Math.min(element.y, element.y2), w: Math.abs(element.x2 - element.x), h: Math.abs(element.y2 - element.y) };
    }
    return { x: element.x, y: element.y, w: element.w, h: element.h };
  }

  function rotatePoint(point, center, angleDegrees) {
    const angle = angleDegrees * Math.PI / 180;
    const cos = Math.cos(angle), sin = Math.sin(angle);
    const dx = point.x - center.x, dy = point.y - center.y;
    return { x: center.x + dx * cos - dy * sin, y: center.y + dx * sin + dy * cos };
  }

  function hitTest(point) {
    for (let index = project.elements.length - 1; index >= 0; index -= 1) {
      const element = project.elements[index];
      if (element.hidden) continue;
      if (element.type === "wall") {
        const distance = distanceToSegment(point, { x: element.x, y: element.y }, { x: element.x2, y: element.y2 });
        if (distance <= .35) return element;
        continue;
      }
      const center = { x: element.x + element.w / 2, y: element.y + element.h / 2 };
      const local = rotatePoint(point, center, -(element.rotation || 0));
      if (local.x >= element.x - .12 && local.x <= element.x + element.w + .12 && local.y >= element.y - .12 && local.y <= element.y + element.h + .12) return element;
    }
    return null;
  }

  function distanceToSegment(point, start, end) {
    const dx = end.x - start.x, dy = end.y - start.y;
    const length2 = dx * dx + dy * dy;
    if (!length2) return Math.hypot(point.x - start.x, point.y - start.y);
    const t = clamp(((point.x - start.x) * dx + (point.y - start.y) * dy) / length2, 0, 1);
    return Math.hypot(point.x - (start.x + t * dx), point.y - (start.y + t * dy));
  }

  function elementCorners(element) {
    const base = {
      nw: { x: element.x, y: element.y },
      ne: { x: element.x + element.w, y: element.y },
      sw: { x: element.x, y: element.y + element.h },
      se: { x: element.x + element.w, y: element.y + element.h }
    };
    const rotation = element.rotation || 0;
    if (!rotation) return base;
    const center = { x: element.x + element.w / 2, y: element.y + element.h / 2 };
    return Object.fromEntries(Object.entries(base).map(([key, point]) => [key, rotatePoint(point, center, rotation)]));
  }

  function normaliseAngle(value) {
    let angle = Number(value) || 0;
    while (angle > 180) angle -= 360;
    while (angle <= -180) angle += 360;
    return angle;
  }

  function selectionControlPositions(element) {
    if (!element || isStructureType(element.type)) return null;
    const rotation = Number(element.rotation) || 0;
    const radians = rotation * Math.PI / 180;
    const center = { x: element.x + element.w / 2, y: element.y + element.h / 2 };
    const topCenter = rotatePoint({ x: center.x, y: element.y }, center, rotation);
    const tangent = { x: Math.cos(radians), y: Math.sin(radians) };
    const outward = { x: Math.sin(radians), y: -Math.cos(radians) };
    const distance = 1.2 / transform.scale;
    const separation = .72 / transform.scale;
    return {
      anchor: topCenter,
      move: {
        x: topCenter.x + outward.x * distance - tangent.x * separation,
        y: topCenter.y + outward.y * distance - tangent.y * separation
      },
      rotate: {
        x: topCenter.x + outward.x * distance + tangent.x * separation,
        y: topCenter.y + outward.y * distance + tangent.y * separation
      }
    };
  }

  function selectionControlAt(point, element) {
    const controls = selectionControlPositions(element);
    if (!controls) return "";
    const radius = .62 / transform.scale;
    if (Math.hypot(point.x - controls.move.x, point.y - controls.move.y) <= radius) return "move-control";
    if (Math.hypot(point.x - controls.rotate.x, point.y - controls.rotate.y) <= radius) return "rotate-control";
    return "";
  }

  function handleAt(point, element) {
    if (!element || element.type === "wall") return "";
    const handles = elementCorners(element);
    return Object.entries(handles).find(([, handle]) => Math.hypot(point.x - handle.x, point.y - handle.y) < .38 / transform.scale)?.[0] || "";
  }

  function handleSigns(handle) {
    return {
      nw: { sx: -1, sy: -1, opposite: "se" },
      ne: { sx: 1, sy: -1, opposite: "sw" },
      sw: { sx: -1, sy: 1, opposite: "ne" },
      se: { sx: 1, sy: 1, opposite: "nw" }
    }[handle] || null;
  }

  function rotatedResizeData(element, handle) {
    const signs = handleSigns(handle);
    if (!signs) return null;
    const corners = elementCorners(element);
    const angle = (Number(element.rotation) || 0) * Math.PI / 180;
    return {
      signs,
      fixed: corners[signs.opposite],
      axisX: { x: Math.cos(angle), y: Math.sin(angle) },
      axisY: { x: -Math.sin(angle), y: Math.cos(angle) }
    };
  }

  function resizeRotatedElement(element, pointer, action) {
    const data = action.resizeData || rotatedResizeData(action.before, action.handle);
    if (!data) return;
    const { signs, fixed, axisX, axisY } = data;
    const delta = { x: pointer.x - fixed.x, y: pointer.y - fixed.y };
    const projectedW = signs.sx * (delta.x * axisX.x + delta.y * axisX.y);
    const projectedH = signs.sy * (delta.x * axisY.x + delta.y * axisY.y);
    const minSize = .25;
    const rawW = Math.max(minSize, projectedW);
    const rawH = Math.max(minSize, projectedH);
    const nextW = isStructureType(element.type) && project.snap ? Math.max(.5, roundTo(rawW, .5)) : rawW;
    const nextH = isStructureType(element.type) && project.snap ? Math.max(.5, roundTo(rawH, .5)) : rawH;
    const dragged = {
      x: fixed.x + signs.sx * nextW * axisX.x + signs.sy * nextH * axisY.x,
      y: fixed.y + signs.sx * nextW * axisX.y + signs.sy * nextH * axisY.y
    };
    const center = { x: (fixed.x + dragged.x) / 2, y: (fixed.y + dragged.y) / 2 };
    element.w = nextW;
    element.h = nextH;
    element.x = center.x - nextW / 2;
    element.y = center.y - nextH / 2;
  }

  function beginSelectedHandleInteraction(point, event) {
    const chosen = selected();
    if (!chosen) return false;
    const handle = handleAt(point, chosen);
    if (handle) {
      pointerState = {
        id: event.pointerId,
        mode: "resize",
        handle,
        start: point,
        before: clone(chosen),
        resizeData: rotatedResizeData(chosen, handle)
      };
      return true;
    }
    const control = selectionControlAt(point, chosen);
    if (control === "move-control") {
      pointerState = { id: event.pointerId, mode: "control-move", start: point, before: clone(chosen) };
      return true;
    }
    if (control === "rotate-control") {
      pointerState = {
        id: event.pointerId,
        mode: "rotate-control",
        center: { x: chosen.x + chosen.w / 2, y: chosen.y + chosen.h / 2 },
        before: clone(chosen)
      };
      return true;
    }
    return false;
  }

  function selectHitForMove(point, event) {
    const hit = hitTest(point);
    if (!hit) return false;
    selectedId = hit.id;
    if (["room", "corridor"].includes(hit.type) && els.floorMaterialTarget) els.floorMaterialTarget.value = "selection";
    renderSelectionPanel();
    renderOverlay();
    renderLayers();
    pointerState = { id: event.pointerId, mode: "move", start: point, before: clone(hit) };
    return true;
  }

  function startPointer(event) {
    if (!project || event.button !== 0) return;
    const point = pointFromEvent(event);
    const activeTool = spaceDown ? "pan" : (propTool ? "prop" : tool);
    els.overlay.setPointerCapture(event.pointerId);

    if (activeTool === "pan") {
      pointerState = { id: event.pointerId, mode: "pan", clientX: event.clientX, clientY: event.clientY, startTransform: { ...transform } };
      return;
    }

    if (activeTool === "select") {
      if (!beginSelectedHandleInteraction(point, event) && !selectHitForMove(point, event)) {
        selectedId = "";
        renderSelectionPanel();
        renderOverlay();
        renderLayers();
        pointerState = { id: event.pointerId, mode: "pan", clientX: event.clientX, clientY: event.clientY, startTransform: { ...transform } };
      }
      return;
    }

    if (activeTool === "eraser") {
      const hit = hitTest(point);
      if (hit) {
        project.elements = project.elements.filter(element => element.id !== hit.id);
        if (selectedId === hit.id) selectedId = "";
        commit(`${TYPE_LABELS[hit.type]} eliminado`);
      }
      return;
    }

    if (activeTool === "prop") {
      // La herramienta permanece activa para colocar muchos objetos seguidos.
      // Solo los tiradores del objeto seleccionado interceptan el clic; sobre
      // cualquier otro punto, incluso encima de otros elementos, se coloca uno nuevo.
      if (beginSelectedHandleInteraction(point, event)) return;
      if ((event.ctrlKey || event.metaKey) && selectHitForMove(point, event)) return;
      if (CUSTOM_LINE_PROP_TYPES.has(propTool)) {
        const start = { x: point.x, y: point.y };
        pointerState = { id: event.pointerId, mode: "draw", drawTool: "prop-line", propType: propTool, start, current: start };
        draft = pointerState;
        renderOverlay();
      } else {
        addProp(propTool, point);
      }
      return;
    }

    if (activeTool === "text") {
      const x = point.x, y = point.y;
      const element = { id: app.uid(), type: "text", x, y, w: 4, h: 1, x2: x + 4, y2: y + 1, rotation: 0, label: "Etiqueta", hidden: false, floorTexture: "" };
      project.elements.push(element);
      selectedId = element.id;
      setTool("select");
      commit("Etiqueta añadida");
      setTimeout(() => { els.elementLabel.focus(); els.elementLabel.select(); }, 0);
      return;
    }

    if (["room", "corridor", "wall"].includes(activeTool)) {
      const start = { x: snapForType(activeTool, point.x), y: snapForType(activeTool, point.y) };
      pointerState = { id: event.pointerId, mode: "draw", drawTool: activeTool, start, current: start };
      draft = pointerState;
      renderOverlay();
    }
  }

  function movePointer(event) {
    if (!project) return;
    const point = pointFromEvent(event);
    els.coordinates.textContent = `${point.x.toFixed(1)} m, ${point.y.toFixed(1)} m`;
    if (!pointerState || pointerState.id !== event.pointerId) return;

    if (pointerState.mode === "pan") {
      transform.x = pointerState.startTransform.x + event.clientX - pointerState.clientX;
      transform.y = pointerState.startTransform.y + event.clientY - pointerState.clientY;
      applyTransform();
      return;
    }

    if (pointerState.mode === "draw") {
      let current = { x: pointerState.drawTool === "prop-line" ? point.x : snapForType(pointerState.drawTool, point.x), y: pointerState.drawTool === "prop-line" ? point.y : snapForType(pointerState.drawTool, point.y) };
      if (pointerState.drawTool === "wall" || pointerState.drawTool === "prop-line") {
        const dx = Math.abs(current.x - pointerState.start.x), dy = Math.abs(current.y - pointerState.start.y);
        if (dx > dy * 1.35) current.y = pointerState.start.y;
        else if (dy > dx * 1.35) current.x = pointerState.start.x;
      }
      pointerState.current = current;
      renderOverlay();
      return;
    }

    const element = selected();
    if (!element) return;
    if (pointerState.mode === "control-move") {
      const dx = point.x - pointerState.start.x;
      const dy = point.y - pointerState.start.y;
      element.x = pointerState.before.x + dx;
      element.y = pointerState.before.y + dy;
      renderAll(false);
      return;
    }

    if (pointerState.mode === "rotate-control") {
      const angleToPointer = Math.atan2(point.y - pointerState.center.y, point.x - pointerState.center.x) * 180 / Math.PI;
      const rawRotation = angleToPointer + 90;
      element.rotation = normaliseAngle(event.shiftKey ? rawRotation : roundTo(rawRotation, 45));
      renderAll(false);
      return;
    }

    if (pointerState.mode === "move") {
      const dx = point.x - pointerState.start.x, dy = point.y - pointerState.start.y;
      if (element.type === "wall") {
        const snappedDx = project.snap ? roundTo(dx) : dx;
        const snappedDy = project.snap ? roundTo(dy) : dy;
        element.x = pointerState.before.x + snappedDx; element.y = pointerState.before.y + snappedDy;
        element.x2 = pointerState.before.x2 + snappedDx; element.y2 = pointerState.before.y2 + snappedDy;
      } else {
        element.x = snapForType(element.type, pointerState.before.x + dx); element.y = snapForType(element.type, pointerState.before.y + dy);
      }
      renderAll(false);
      return;
    }

    if (pointerState.mode === "resize") {
      resizeRotatedElement(element, point, pointerState);
      renderAll(false);
    }
  }

  function stopPointer(event) {
    if (!pointerState || pointerState.id !== event.pointerId) return;
    const action = pointerState;
    pointerState = null;
    draft = null;
    if (els.overlay.hasPointerCapture(event.pointerId)) els.overlay.releasePointerCapture(event.pointerId);

    if (action.mode === "draw") {
      const end = action.current || action.start;
      if (action.drawTool === "wall") {
        if (Math.hypot(end.x - action.start.x, end.y - action.start.y) >= .5) {
          const element = { id: app.uid(), type: "wall", x: action.start.x, y: action.start.y, x2: end.x, y2: end.y, w: 0, h: 0, rotation: 0, label: "", hidden: false, floorTexture: "" };
          project.elements.push(element); selectedId = element.id; commit("Pared añadida");
        } else renderOverlay();
      } else if (action.drawTool === "prop-line") {
        const dx = end.x - action.start.x, dy = end.y - action.start.y;
        const length = Math.hypot(dx, dy);
        if (length >= .5) {
          const thickness = { door: .34, "double-door": .42, "secret-door": .34 }[action.propType] || .34;
          const element = { id: app.uid(), type: action.propType, x: (action.start.x + end.x) / 2 - length / 2, y: (action.start.y + end.y) / 2 - thickness / 2, w: length, h: thickness, x2: 0, y2: 0, rotation: Math.atan2(dy, dx) * 180 / Math.PI, label: "", hidden: false, floorTexture: "" };
          project.elements.push(element); selectedId = element.id; commit(`${TYPE_LABELS[action.propType]} añadida`);
        } else renderOverlay();
      } else {
        const x = Math.min(action.start.x, end.x), y = Math.min(action.start.y, end.y);
        const w = Math.abs(end.x - action.start.x), h = Math.abs(end.y - action.start.y);
        if (w >= 1 && h >= 1) {
          const element = { id: app.uid(), type: action.drawTool, x, y, w, h, x2: x + w, y2: y + h, rotation: 0, label: "", hidden: false, floorTexture: "" };
          project.elements.push(element); selectedId = element.id; commit(`${TYPE_LABELS[action.drawTool]} añadida`);
        } else renderOverlay();
      }
      return;
    }

    if (["move", "resize", "control-move", "rotate-control"].includes(action.mode)) commit("Elemento actualizado");
  }

  function addProp(type, point) {
    const [w, h] = PROP_DEFAULTS[type] || [1, 1];
    const x = point.x - w / 2, y = point.y - h / 2;
    const element = { id: app.uid(), type, x, y, w, h, x2: x + w, y2: y + h, rotation: 0, label: "", hidden: false, floorTexture: "", variant: type === "statue" ? "gladiator" : "", customImageData: "", customImageName: "", customImageType: "", customImageAspect: 1 };
    project.elements.push(element);
    selectedId = element.id;
    commit(`${TYPE_LABELS[type]} añadido`);
  }

  function renderAll(updatePanels = true) {
    if (!project) return;
    renderBase();
    renderOverlay();
    if (updatePanels) {
      renderSelectionPanel();
      renderLayers();
    }
  }

  function renderBase() {
    const context = els.canvas.getContext("2d");
    renderProject(context, project, EDIT_CELL, { grid: project.gridVisible });
  }

  function renderOverlay() {
    const context = els.overlay.getContext("2d");
    context.clearRect(0, 0, els.overlay.width, els.overlay.height);
    context.save();
    context.scale(EDIT_CELL, EDIT_CELL);
    context.lineWidth = 2 / EDIT_CELL / transform.scale;

    if (draft?.mode === "draw") {
      const start = draft.start, end = draft.current || start;
      context.strokeStyle = "#ef8b3b";
      context.fillStyle = "rgba(239,139,59,.16)";
      context.setLineDash([.22 / transform.scale, .16 / transform.scale]);
      if (draft.drawTool === "wall" || draft.drawTool === "prop-line") {
        context.beginPath(); context.moveTo(start.x, start.y); context.lineTo(end.x, end.y); context.stroke();
      } else {
        const x = Math.min(start.x, end.x), y = Math.min(start.y, end.y), w = Math.abs(end.x - start.x), h = Math.abs(end.y - start.y);
        context.fillRect(x, y, w, h); context.strokeRect(x, y, w, h);
      }
    }

    const element = selected();
    if (element && !element.hidden) {
      context.setLineDash([.18 / transform.scale, .12 / transform.scale]);
      context.strokeStyle = "#f2b36f";
      context.fillStyle = "#fff2da";
      if (element.type === "wall") {
        context.beginPath(); context.moveTo(element.x, element.y); context.lineTo(element.x2, element.y2); context.stroke();
        drawHandle(context, element.x, element.y); drawHandle(context, element.x2, element.y2);
      } else {
        context.save();
        const centerX = element.x + element.w / 2, centerY = element.y + element.h / 2;
        context.translate(centerX, centerY); context.rotate((element.rotation || 0) * Math.PI / 180); context.translate(-centerX, -centerY);
        context.strokeRect(element.x, element.y, element.w, element.h);
        context.restore();
        const corners = elementCorners(element);
        drawHandle(context, corners.nw.x, corners.nw.y); drawHandle(context, corners.ne.x, corners.ne.y);
        drawHandle(context, corners.sw.x, corners.sw.y); drawHandle(context, corners.se.x, corners.se.y);
        const controls = selectionControlPositions(element);
        if (controls) drawSelectionControls(context, controls);
      }
    }
    context.restore();
  }

  function drawSelectionControls(context, controls) {
    const radius = .48 / transform.scale;
    context.save();
    context.setLineDash([]);
    context.lineWidth = 2 / EDIT_CELL / transform.scale;
    context.strokeStyle = "rgba(255,226,184,.82)";
    context.beginPath();
    context.moveTo(controls.anchor.x, controls.anchor.y);
    context.lineTo(controls.move.x, controls.move.y);
    context.moveTo(controls.anchor.x, controls.anchor.y);
    context.lineTo(controls.rotate.x, controls.rotate.y);
    context.stroke();
    drawControlCircle(context, controls.move, radius, "#2f8fa3", "✥");
    drawControlCircle(context, controls.rotate, radius, "#d97732", "↻");
    context.restore();
  }

  function drawControlCircle(context, point, radius, fill, symbol) {
    context.beginPath();
    context.fillStyle = fill;
    context.strokeStyle = "#fff2da";
    context.lineWidth = 2 / EDIT_CELL / transform.scale;
    context.arc(point.x, point.y, radius, 0, Math.PI * 2);
    context.fill();
    context.stroke();
    context.fillStyle = "#ffffff";
    context.font = `700 ${.52 / transform.scale}px system-ui, sans-serif`;
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText(symbol, point.x, point.y + .015 / transform.scale);
  }

  function drawHandle(context, x, y) {
    const size = .22 / transform.scale;
    context.fillRect(x - size / 2, y - size / 2, size, size);
    context.strokeRect(x - size / 2, y - size / 2, size, size);
  }

  function renderProject(context, data, cellSize, options = {}) {
    const width = data.widthCells * cellSize, height = data.heightCells * cellSize;
    context.clearRect(0, 0, width, height);
    context.save();
    context.fillStyle = "#090b0c";
    context.fillRect(0, 0, width, height);
    context.scale(cellSize, cellSize);

    const floorPlan = buildFloorPlan(data);
    floorPlan.cells.forEach(cell => drawFloorCell(context, cell, data.style, cellSize));
    drawFloorBoundaries(context, floorPlan, data.style, cellSize);
    data.elements.filter(element => !element.hidden && !["room", "corridor", "wall", "text", "trap", "secret", "poi"].includes(element.type)).forEach(element => drawProp(context, element, data.style, cellSize));
    data.elements.filter(element => !element.hidden && element.type === "text").forEach(element => drawText(context, element, data.style));

    if (options.grid) drawGrid(context, data);
    context.restore();
  }

  function buildFloorPlan(data) {
    const elements = data.elements.filter(element => !element.hidden && ["room", "corridor"].includes(element.type));
    const xs = new Set([0, data.widthCells]);
    const ys = new Set([0, data.heightCells]);
    elements.forEach(element => {
      xs.add(Number(element.x) || 0); xs.add((Number(element.x) || 0) + (Number(element.w) || 0));
      ys.add(Number(element.y) || 0); ys.add((Number(element.y) || 0) + (Number(element.h) || 0));
    });
    const xList = [...xs].sort((a, b) => a - b);
    const yList = [...ys].sort((a, b) => a - b);
    const cells = [];
    const occupancy = new Map();
    for (let yi = 0; yi < yList.length - 1; yi += 1) {
      for (let xi = 0; xi < xList.length - 1; xi += 1) {
        const x1 = xList[xi], x2 = xList[xi + 1], y1 = yList[yi], y2 = yList[yi + 1];
        if (x2 <= x1 || y2 <= y1) continue;
        const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
        let source = null;
        for (let index = elements.length - 1; index >= 0; index -= 1) {
          const element = elements[index];
          if (cx > element.x - 1e-6 && cx < element.x + element.w + 1e-6 && cy > element.y - 1e-6 && cy < element.y + element.h + 1e-6) {
            if (!source || element.type === "room") source = element;
            if (element.type === "room") break;
          }
        }
        if (!source) continue;
        const cell = { x: x1, y: y1, w: x2 - x1, h: y2 - y1, kind: source.type, source, xi, yi };
        cells.push(cell);
        occupancy.set(`${xi}:${yi}`, cell);
      }
    }
    const rawEdges = [];
    cells.forEach(cell => {
      const top = occupancy.get(`${cell.xi}:${cell.yi - 1}`);
      const right = occupancy.get(`${cell.xi + 1}:${cell.yi}`);
      const bottom = occupancy.get(`${cell.xi}:${cell.yi + 1}`);
      const left = occupancy.get(`${cell.xi - 1}:${cell.yi}`);
      if (!top) rawEdges.push({ o: "h", x1: cell.x, x2: cell.x + cell.w, y: cell.y });
      if (!bottom) rawEdges.push({ o: "h", x1: cell.x, x2: cell.x + cell.w, y: cell.y + cell.h });
      if (!left) rawEdges.push({ o: "v", y1: cell.y, y2: cell.y + cell.h, x: cell.x });
      if (!right) rawEdges.push({ o: "v", y1: cell.y, y2: cell.y + cell.h, x: cell.x + cell.w });
    });
    data.elements.filter(element => !element.hidden && element.type === "wall").forEach(element => {
      rawEdges.push(wallToEdge(element));
    });
    return { cells, edges: mergeEdges(rawEdges) };
  }

  function wallToEdge(element) {
    if (Math.abs((element.x2 - element.x)) >= Math.abs((element.y2 - element.y))) {
      const y = (element.y + element.y2) / 2;
      return { o: "h", x1: Math.min(element.x, element.x2), x2: Math.max(element.x, element.x2), y };
    }
    const x = (element.x + element.x2) / 2;
    return { o: "v", y1: Math.min(element.y, element.y2), y2: Math.max(element.y, element.y2), x };
  }

  function mergeEdges(edges) {
    const horizontal = edges.filter(edge => edge.o === "h").sort((a, b) => a.y - b.y || a.x1 - b.x1);
    const vertical = edges.filter(edge => edge.o === "v").sort((a, b) => a.x - b.x || a.y1 - b.y1);
    const merged = [];
    for (const group of [horizontal, vertical]) {
      for (const edge of group) {
        const last = merged[merged.length - 1];
        if (!last || last.o !== edge.o) { merged.push({ ...edge }); continue; }
        if (edge.o === "h" && Math.abs(last.y - edge.y) < 1e-6 && edge.x1 <= last.x2 + 1e-6) last.x2 = Math.max(last.x2, edge.x2);
        else if (edge.o === "v" && Math.abs(last.x - edge.x) < 1e-6 && edge.y1 <= last.y2 + 1e-6) last.y2 = Math.max(last.y2, edge.y2);
        else merged.push({ ...edge });
      }
    }
    return merged;
  }

  function drawFloorCell(context, cell, style, cellSize) {
    context.save();
    const material = effectiveFloorMaterial(cell.source);
    const base = material.color || style.floorColor;
    const baseColor = cell.kind === "corridor" ? colorMix(base, "#000000", .1) : base;
    const originX = Number(cell.source?.x) || 0;
    const originY = Number(cell.source?.y) || 0;
    context.translate(originX, originY);
    context.fillStyle = texturePattern(context, material.texture || style.floorTexture, baseColor, cellSize, {
      scale: material.scale, rotation: material.rotation, intensity: material.intensity, mode: material.mode,
      customData: material.customData, mapWidth: Number(cell.source?.w) || project.widthCells, mapHeight: Number(cell.source?.h) || project.heightCells
    });
    context.fillRect(cell.x - originX, cell.y - originY, cell.w, cell.h);
    if (style.relief > 0) {
      const localX = cell.x - originX, localY = cell.y - originY;
      const gradient = context.createLinearGradient(localX, localY, localX, localY + Math.min(2, cell.h));
      gradient.addColorStop(0, `rgba(255,255,255,${(cell.kind === "corridor" ? .045 : .08) * style.relief})`);
      gradient.addColorStop(1, "rgba(255,255,255,0)");
      context.fillStyle = gradient;
      context.fillRect(localX, localY, cell.w, Math.min(2, cell.h));
    }
    context.restore();
  }

  function drawFloorBoundaries(context, floorPlan, style, cellSize) {
    if (!floorPlan.edges.length) return;
    const caveLike = style.wallTexture === "cave";
    const wallWidth = caveLike ? (.12 + Number(style.lineWidth || 4) * .01) : (.34 + Number(style.lineWidth || 4) * .018);
    context.save();
    context.lineCap = caveLike ? "round" : "square";
    context.lineJoin = caveLike ? "round" : "miter";
    context.strokeStyle = `rgba(0,0,0,${style.shadowOpacity})`;
    context.lineWidth = wallWidth + (caveLike ? .08 : .22) * style.relief;
    context.shadowColor = `rgba(0,0,0,${style.shadowOpacity})`;
    context.shadowBlur = (caveLike ? .12 : .28) * style.relief;
    context.shadowOffsetX = (caveLike ? .04 : .12) * style.relief;
    context.shadowOffsetY = (caveLike ? .06 : .17) * style.relief;
    context.beginPath();
    floorPlan.edges.forEach(edge => {
      if (edge.o === "h") { context.moveTo(edge.x1, edge.y); context.lineTo(edge.x2, edge.y); }
      else { context.moveTo(edge.x, edge.y1); context.lineTo(edge.x, edge.y2); }
    });
    context.stroke();
    context.shadowColor = "transparent";
    context.strokeStyle = texturePattern(context, `wall-${style.wallTexture}`, style.wallColor, cellSize, { scale: style.wallTextureScale, rotation: style.wallTextureRotation, intensity: style.wallTextureIntensity, mode: style.wallTextureMode, customData: style.wallCustomTextureData, mapWidth: project.widthCells, mapHeight: project.heightCells });
    context.lineWidth = wallWidth;
    context.beginPath();
    floorPlan.edges.forEach(edge => {
      if (edge.o === "h") { context.moveTo(edge.x1, edge.y); context.lineTo(edge.x2, edge.y); }
      else { context.moveTo(edge.x, edge.y1); context.lineTo(edge.x, edge.y2); }
    });
    context.stroke();
    if (!caveLike) {
      context.strokeStyle = colorMix(style.wallColor, "#ffffff", .28 * style.relief);
      context.lineWidth = .045;
      context.beginPath();
      floorPlan.edges.forEach(edge => {
        if (edge.o === "h") { context.moveTo(edge.x1, edge.y); context.lineTo(edge.x2, edge.y); }
        else { context.moveTo(edge.x, edge.y1); context.lineTo(edge.x, edge.y2); }
      });
      context.stroke();
    }
    context.restore();
  }

  function drawWall(context, element, style, cellSize) {
    context.save();
    const caveLike = style.wallTexture === "cave";
    const width = caveLike ? (.1 + Number(style.lineWidth || 4) * .008) : (.32 + Number(style.lineWidth || 4) * .02);
    context.lineCap = caveLike ? "round" : "square";
    context.strokeStyle = `rgba(0,0,0,${style.shadowOpacity})`;
    context.lineWidth = width + (caveLike ? .06 : .2) * style.relief;
    context.shadowColor = `rgba(0,0,0,${style.shadowOpacity})`;
    context.shadowBlur = (caveLike ? .1 : .25) * style.relief;
    context.shadowOffsetX = caveLike ? .04 : .1;
    context.shadowOffsetY = caveLike ? .06 : .14;
    context.beginPath();
    context.moveTo(element.x, element.y);
    context.lineTo(element.x2, element.y2);
    context.stroke();
    context.shadowColor = "transparent";
    context.strokeStyle = texturePattern(context, `wall-${style.wallTexture}`, style.wallColor, cellSize, { scale: style.wallTextureScale, rotation: style.wallTextureRotation, intensity: style.wallTextureIntensity, mode: style.wallTextureMode, customData: style.wallCustomTextureData, mapWidth: project.widthCells, mapHeight: project.heightCells });
    context.lineWidth = width;
    context.beginPath();
    context.moveTo(element.x, element.y);
    context.lineTo(element.x2, element.y2);
    context.stroke();
    context.restore();
  }

  function drawGrid(context, data) {
    context.save();
    context.strokeStyle = hexToRgba(data.style.gridColor, .34);
    context.lineWidth = .022;
    context.beginPath();
    for (let x = 0; x <= data.widthCells; x += 1) { context.moveTo(x, 0); context.lineTo(x, data.heightCells); }
    for (let y = 0; y <= data.heightCells; y += 1) { context.moveTo(0, y); context.lineTo(data.widthCells, y); }
    context.stroke();
    context.restore();
  }

  function drawText(context, element, style) {
    context.save();
    const centerX = element.x + element.w / 2, centerY = element.y + element.h / 2;
    context.translate(centerX, centerY); context.rotate((element.rotation || 0) * Math.PI / 180);
    context.fillStyle = style.textColor;
    context.strokeStyle = "rgba(0,0,0,.8)";
    context.lineWidth = .08;
    context.font = `700 ${Math.max(.45, element.h * .58)}px Georgia, serif`;
    context.textAlign = "center"; context.textBaseline = "middle";
    context.strokeText(element.label || "Etiqueta", 0, 0); context.fillText(element.label || "Etiqueta", 0, 0);
    context.restore();
  }

  function objectImageRecord(source) {
    if (!source) return null;
    if (objectImageCache.has(source)) return objectImageCache.get(source);
    const image = new Image();
    const record = { image, status: "loading", promise: null, refreshQueued: false };
    record.promise = new Promise(resolve => {
      image.onload = () => { record.status = "loaded"; resolve(record); };
      image.onerror = () => { record.status = "error"; resolve(record); };
    });
    image.decoding = "async";
    image.src = source;
    objectImageCache.set(source, record);
    return record;
  }

  function drawContainedImage(context, image, width, height) {
    const naturalWidth = image.naturalWidth || image.width || 1;
    const naturalHeight = image.naturalHeight || image.height || 1;
    const scale = Math.min(Math.abs(width) / naturalWidth, Math.abs(height) / naturalHeight);
    const drawWidth = naturalWidth * scale;
    const drawHeight = naturalHeight * scale;
    context.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  }

  function drawElementImage(context, element, x, y, width, height, style) {
    const source = elementImageSource(element);
    if (!source) return false;
    const record = objectImageRecord(source);
    if (!record || record.status === "error") return false;
    context.save();
    context.shadowColor = `rgba(0,0,0,${Math.min(.7, Number(style.shadowOpacity || 0) + .12)})`;
    context.shadowBlur = .2 * Number(style.relief || 0);
    context.shadowOffsetX = .08;
    context.shadowOffsetY = .12;
    if (record.status === "loaded") {
      drawContainedImage(context, record.image, width, height);
    } else {
      context.shadowColor = "transparent";
      context.fillStyle = "rgba(255,255,255,.06)";
      context.strokeStyle = "rgba(255,255,255,.22)";
      context.setLineDash([.12, .1]);
      context.fillRect(x, y, width, height);
      context.strokeRect(x, y, width, height);
      context.setLineDash([]);
      if (!record.refreshQueued) {
        record.refreshQueued = true;
        record.promise.then(() => {
          record.refreshQueued = false;
          if (state().view === "dungeon") renderAll(false);
        });
      }
    }
    context.restore();
    return true;
  }

  async function preloadObjectImages(data = project) {
    if (!data) return;
    const sources = [
      ...data.elements.map(elementImageSource),
      data.style?.floorCustomTextureData, data.style?.wallCustomTextureData,
      ...data.elements.map(element => element.floorMaterial?.customData)
    ].filter(Boolean);
    await Promise.all([...new Set(sources)].map(source => objectImageRecord(source)?.promise).filter(Boolean));
  }

  function drawProp(context, element, style, cellSize) {
    context.save();
    const cx = element.x + element.w / 2, cy = element.y + element.h / 2;
    context.translate(cx, cy); context.rotate((element.rotation || 0) * Math.PI / 180);
    context.shadowColor = `rgba(0,0,0,${style.shadowOpacity})`;
    context.shadowBlur = .18 * style.relief;
    context.shadowOffsetX = .08; context.shadowOffsetY = .12;
    context.lineWidth = .08;
    context.strokeStyle = style.lineColor;
    context.fillStyle = style.objectColor;
    const x = -element.w / 2, y = -element.h / 2, w = element.w, h = element.h;

    if (drawElementImage(context, element, x, y, w, h, style)) {
      context.shadowColor = "transparent";
      context.restore();
      return;
    }

    switch (element.type) {
      case "door": case "double-door": case "secret-door": drawDoor(context, element.type, x, y, w, h, style); break;
      case "stairs-up": case "stairs-down": drawStairs(context, element.type, x, y, w, h, style); break;
      case "grate": drawGrate(context, x, y, w, h, style); break;
      case "window": drawWindow(context, x, y, w, h, style); break;
      case "column": drawColumn(context, x, y, w, h, style); break;
      case "pit": drawPit(context, x, y, w, h, style); break;
      case "bridge": drawBridge(context, x, y, w, h, style); break;
      case "table": drawTable(context, x, y, w, h, style); break;
      case "chair": drawChair(context, x, y, w, h, style); break;
      case "bed": drawBed(context, x, y, w, h, style); break;
      case "shelf": case "wardrobe": drawStorage(context, element.type, x, y, w, h, style); break;
      case "chest": drawChest(context, x, y, w, h, style); break;
      case "barrel": case "brazier": drawRoundProp(context, element.type, x, y, w, h, style); break;
      case "crate": drawCrate(context, x, y, w, h, style); break;
      case "altar": drawAltar(context, x, y, w, h, style); break;
      case "statue": drawStatue(context, element.variant || "knight", x, y, w, h, style); break;
      case "portal-rect": case "portal-arch": drawPortal(context, element.type, x, y, w, h, style); break;
      case "platform": case "round-platform": case "pedestal": drawPlatform(context, element.type, x, y, w, h, style); break;
      case "torch": drawTorch(context, x, y, w, h, style); break;
      case "trap": case "secret": case "poi": drawMarkerProp(context, element.type, x, y, w, h, style); break;
      default: context.fillRect(x, y, w, h); context.strokeRect(x, y, w, h);
    }
    context.shadowColor = "transparent";
    context.restore();
  }

  function drawDoor(ctx, type, x, y, w, h, style) {
    ctx.save();
    ctx.fillStyle = style.doorColor;
    ctx.strokeStyle = style.lineColor;
    ctx.lineWidth = Math.max(.035, Math.min(w, h) * .08);
    ctx.fillRect(x, y, w, h);
    ctx.strokeRect(x, y, w, h);
    const inset = Math.min(Math.abs(w), Math.abs(h)) * .18;
    ctx.strokeStyle = colorMix(style.doorColor, "#ffffff", .38);
    ctx.lineWidth = Math.max(.025, Math.min(w, h) * .055);
    if (type === "double-door") {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(0, y + h); ctx.stroke();
      ctx.strokeRect(x + inset, y + inset, Math.max(.02, w / 2 - inset * 1.5), Math.max(.02, h - inset * 2));
      ctx.strokeRect(inset * .5, y + inset, Math.max(.02, w / 2 - inset * 1.5), Math.max(.02, h - inset * 2));
      ctx.fillStyle = colorMix(style.doorColor, "#f1cf73", .55);
      const knob = Math.max(.025, Math.min(w, h) * .1);
      ctx.beginPath(); ctx.arc(-knob * 1.8, 0, knob, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(knob * 1.8, 0, knob, 0, Math.PI * 2); ctx.fill();
    } else {
      ctx.strokeRect(x + inset, y + inset, Math.max(.02, w - inset * 2), Math.max(.02, h - inset * 2));
      ctx.fillStyle = colorMix(style.doorColor, "#f1cf73", .55);
      const knob = Math.max(.025, Math.min(w, h) * .1);
      ctx.beginPath(); ctx.arc(w * .28, 0, knob, 0, Math.PI * 2); ctx.fill();
    }
    if (type === "secret-door") {
      ctx.setLineDash([.18, .12]); ctx.strokeStyle = "#d8c998"; ctx.strokeRect(x, y, w, h); ctx.setLineDash([]);
      ctx.fillStyle = "#efe1b0"; ctx.font = `${Math.max(.35, h * 1.3)}px Georgia`; ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText("?", 0, 0);
    }
    ctx.restore();
  }
  function drawStairs(ctx, type, x, y, w, h, style) {
    ctx.fillStyle = colorMix(style.floorColor, "#000000", .12); ctx.fillRect(x, y, w, h); ctx.strokeRect(x, y, w, h);
    ctx.strokeStyle = colorMix(style.objectColor, "#ffffff", .35); ctx.lineWidth = .045;
    const count = Math.max(4, Math.round(h / .45));
    for (let index = 1; index < count; index += 1) { const py = y + h * index / count; ctx.beginPath(); ctx.moveTo(x, py); ctx.lineTo(x + w, py); ctx.stroke(); }
    ctx.fillStyle = style.textColor; ctx.font = `${Math.min(w, h) * .35}px sans-serif`; ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText(type === "stairs-up" ? "↑" : "↓", 0, 0);
  }
  function drawGrate(ctx, x, y, w, h, style) {
    ctx.strokeStyle = colorMix(style.lineColor, "#ffffff", .25); ctx.lineWidth = .055;
    const bars = Math.max(3, Math.round(w / .25));
    for (let i = 0; i <= bars; i += 1) { const px = x + w * i / bars; ctx.beginPath(); ctx.moveTo(px, y - .12); ctx.lineTo(px, y + h + .12); ctx.stroke(); }
    ctx.strokeRect(x, y, w, h);
  }
