  async function importImageForSelected(file) {
    const element = selected();
    if (!element || !isImageEligible(element) || !file) return;
    const allowed = new Set(["image/png", "image/svg+xml", "image/webp", "image/jpeg"]);
    const extensionOk = /\.(png|svg|webp|jpe?g)$/i.test(file.name || "");
    if (!allowed.has(file.type) && !extensionOk) {
      alert("Selecciona una imagen PNG, SVG, WebP o JPG.");
      return;
    }
    try {
      const rasterized = await rasterizeImportedImage(file);
      const record = objectImageRecord(rasterized.dataUrl);
      await record.promise;
      if (record.status !== "loaded") throw new Error("La imagen no se ha podido preparar.");
      element.customImageData = rasterized.dataUrl;
      element.customImageName = String(file.name || "Imagen importada").slice(0, 180);
      element.customImageType = "image/png";
      element.customImageAspect = rasterized.width / rasterized.height;
      try {
        await saveRecentObjectAsset(element.type, rasterized, element.customImageName);
      } catch (libraryError) {
        console.warn("La imagen se aplicó, pero no pudo guardarse en archivos recientes.", libraryError);
      }
      commit("Imagen del objeto importada y guardada en archivos recientes");
    } catch (error) {
      console.error(error);
      alert(error.message || "No se pudo importar la imagen.");
    } finally {
      if (els.elementImageInput) els.elementImageInput.value = "";
    }
  }

